        unordered_map<int,int> ump;
        int sum=0,n=nums.size();
        ump[0]=-1;
        for(int i=0;i<n;i++)
        {
            sum+=nums[i];
            if(k)
                sum%=k;
            if(ump.find(sum)!=ump.end())
            {
                if(i-ump[sum]>1)
